"""Apply the separate, opt-in experiment to a pinned standard DXVK checkout."""
import argparse
from pathlib import Path
import shutil
import subprocess

ROOT = Path(__file__).resolve().parents[2]
UPSTREAM = "2b1a284f8453baa2bd193709b67e5183074c74ba"


def prepare(source):
    actual = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=source, text=True).strip()
    if actual != UPSTREAM:
        raise ValueError(f"Wrong upstream commit: {actual}")
    status = subprocess.check_output(["git", "status", "--porcelain"], cwd=source, text=True)
    if status:
        raise ValueError("Preserve the existing changes and use a clean DXVK checkout")
    patch = ROOT / "patches/dxvk-memory-experiment.patch"
    subprocess.run(["git", "apply", "--check", str(patch)], cwd=source, check=True)
    subprocess.run(["git", "apply", str(patch)], cwd=source, check=True)
    shutil.copy2(Path(__file__).with_name("bridge_memory_tracking.h"), source / "src/dxvk/bridge_memory_tracking.h")
    print(f"Prepared modified standard DXVK 2.6.1 mem1 at {source}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", type=Path, required=True)
    prepare(parser.parse_args().source.resolve())
